import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K,
    int stride, int padding, int dilation,
    int groups, int Cin_per_group, int Cout_per_group,
    int Do, int Ho, int Wo)
{
  const int n = blockIdx.z;
  const int P_total = Do * Ho * Wo;
  const int p = blockIdx.x * blockDim.x + threadIdx.x;

  // Strides for X (per-batch tensor)
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  // Strides for Y (per-batch tensor)
  const int64_t sYn = (int64_t)Cout * Do * Ho * Wo;
  const int64_t sYc = (int64_t)Do * Ho * Wo;
  const int64_t sYd = (int64_t)Ho * Wo;
  const int64_t sYh = (int64_t)Wo;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Do, Ho, Wo),
      make_stride(sYc, sYd, sYh, Int<1>{}));

  // Weight tensor: (Cout, Cin_per_group, K, K, K)
  const int K3 = K * K * K;
  const int wCstride = Cin_per_group * K3;

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin_per_group, K, K, K),
      make_stride(wCstride, K3, K * K, K, Int<1>{}));

  // Shared memory: cache the entire weight tensor for this block
  extern __shared__ unsigned char smem_raw[];
  T* smem = reinterpret_cast<T*>(smem_raw);
  const int weight_size = Cout * Cin_per_group * K3;

  auto sW = make_tensor(
      make_smem_ptr(smem),
      make_shape(Cout, Cin_per_group, K, K, K),
      make_stride(wCstride, K3, K * K, K, Int<1>{}));

  for (int idx = threadIdx.x; idx < weight_size; idx += blockDim.x) {
    smem[idx] = W[idx];
  }
  __syncthreads();

  if (p >= P_total) return;

  const int HoWo = Ho * Wo;
  const int od = p / HoWo;
  const int rem = p - od * HoWo;
  const int oh = rem / Wo;
  const int ow = rem - oh * Wo;

  const int id0 = od * stride - padding;
  const int ih0 = oh * stride - padding;
  const int iw0 = ow * stride - padding;

  for (int co = 0; co < Cout; ++co) {
    const int g = co / Cout_per_group;
    const int ci_base = g * Cin_per_group;

    float acc = (B != nullptr) ? (float)B[co] : 0.0f;

    for (int ci = 0; ci < Cin_per_group; ++ci) {
      const int ci_global = ci_base + ci;

      for (int kd = 0; kd < K; ++kd) {
        const int id = id0 + kd * dilation;
        if ((unsigned)id >= (unsigned)D) continue;

        for (int kh = 0; kh < K; ++kh) {
          const int ih = ih0 + kh * dilation;
          if ((unsigned)ih >= (unsigned)H) continue;

          for (int kw = 0; kw < K; ++kw) {
            const int iw = iw0 + kw * dilation;
            if ((unsigned)iw >= (unsigned)Win) continue;

            float xval = (float)mX(ci_global, id, ih, iw);
            float wval = (float)sW(co, ci, kd, kh, kw);
            acc += xval * wval;
          }
        }
      }
    }

    mY(co, od, oh, ow) = static_cast<T>(acc);
  }
}

torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, C, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, K, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);

  int64_t Cout = w.size(0);
  int64_t Cin_per_group = w.size(1);
  int64_t K = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic");
  TORCH_CHECK(Cin % groups == 0, "Cin must be divisible by groups");
  TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
  TORCH_CHECK(Cin / groups == Cin_per_group, "weight Cin/groups mismatch");
  int64_t Cout_per_group = Cout / groups;

  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Do = (D + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Ho = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wo = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Do > 0 && Ho > 0 && Wo > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Do, Ho, Wo}, x.options());

  constexpr int Threads = 256;
  const int64_t P_total = Do * Ho * Wo;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + Threads - 1) / Threads),
      1u,
      (unsigned)N
  );

  size_t smem_bytes = (size_t)Cout * Cin_per_group * K * K * K * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }

  conv3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K,
      (int)stride, (int)padding, (int)dilation,
      (int)groups, (int)Cin_per_group, (int)Cout_per_group,
      (int)Do, (int)Ho, (int)Wo
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution (square kernel) implemented with a single custom
    CUDA kernel built using CuTe tensors/layouts. The kernel caches the full
    weight tensor for a (n, out-channel-group) block in shared memory and
    cooperatively computes a tile of output spatial positions across threads.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False) -> None:
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        Cin_per_group = self.in_channels // self.groups
        K = self.kernel_size

        self.weight = nn.Parameter(torch.empty(self.out_channels, Cin_per_group, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

